package main

import (
	"bufio"
	"fmt"
	"os"
)

const SIZE = 110

var dirs = [4][2]int{{0, 1}, {1, 0}, {0, -1}, {-1, 0}}

type Node struct {
	x, y, step int
}

func bfs(grid [SIZE][SIZE]int, sx, sy, tx, ty int) int {
	visited := [SIZE][SIZE]bool{}
	q := make([]Node, 0, SIZE*SIZE)
	q = append(q, Node{sx, sy, 0})
	visited[sx][sy] = true

	head := 0
	for head < len(q) {
		cur := q[head]
		head++

		if cur.x == tx && cur.y == ty {
			return cur.step
		}

		for _, d := range dirs {
			nx, ny := cur.x+d[0], cur.y+d[1]
			if nx < 0 || nx >= SIZE || ny < 0 || ny >= SIZE {
				continue
			}
			if grid[nx][ny] == 1 || visited[nx][ny] {
				continue
			}
			visited[nx][ny] = true
			q = append(q, Node{nx, ny, cur.step + 1})
		}
	}
	return -1
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	s := scanner.Text()
	n := len(s)

	x, y := 0, 0
	minX, minY := 0, 0

	for i := 0; i < n; i++ {
		switch s[i] {
		case 'L':
			y--
		case 'R':
			y++
		case 'U':
			x--
		case 'D':
			x++
		}
		if x < minX {
			minX = x
		}
		if y < minY {
			minY = y
		}
	}

	offsetX, offsetY := -minX, -minY

	var grid [SIZE][SIZE]int
	for i := 0; i < SIZE; i++ {
		for j := 0; j < SIZE; j++ {
			grid[i][j] = 1
		}
	}

	cx, cy := offsetX, offsetY
	for i := 0; i < n; i++ {
		switch s[i] {
		case 'L':
			cy--
		case 'R':
			cy++
		case 'U':
			cx--
		case 'D':
			cx++
		}
		grid[cx][cy] = 0
	}

	ans := bfs(grid, offsetX, offsetY, cx, cy)

	if ans == n {
		fmt.Println("OK")
	} else {
		fmt.Println("BUG")
	}
}

package main

import (
	"container/heap"
	"fmt"
)

const size = 110

var vis [size][size]int
var dx = [4]int{0, 1, 0, -1}
var dy = [4]int{1, 0, -1, 0}

type Node struct {
	x, y, step int
}

type PriorityQueue []*Node

func (pq PriorityQueue) Len() int { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool {
	return pq[i].step < pq[j].step
}
func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
}
func (pq *PriorityQueue) Push(x interface{}) {
	*pq = append(*pq, x.(*Node))
}
func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[0 : n-1]
	return item
}

func bfs(l, u, xi, yi int) int {
	pq := make(PriorityQueue, 0)
	heap.Init(&pq)
	start := &Node{x: l, y: u, step: 0}
	heap.Push(&pq, start)
	vis[l][u] = 1

	for pq.Len() > 0 {
		e := heap.Pop(&pq).(*Node)
		if e.x == xi && e.y == yi {
			return e.step
		}
		for i := 0; i < 4; i++ {
			nx := e.x + dx[i]
			ny := e.y + dy[i]
			if nx < 0 || ny < 0 || nx >= size || ny >= size {
				continue
			}
			if vis[nx][ny] == 1 {
				continue
			}
			vis[nx][ny] = 1
			heap.Push(&pq, &Node{x: nx, y: ny, step: e.step + 1})
		}
	}
	return -1
}

func main() {
	var s string
	fmt.Scanln(&s)
	lenS := len(s)

	x, y := 0, 0
	minX, minY := 0, 0

	for i := 0; i < lenS; i++ {
		switch s[i] {
		case 'L':
			y--
		case 'R':
			y++
		case 'U':
			x--
		case 'D':
			x++
		}
		if x < minX {
			minX = x
		}
		if y < minY {
			minY = y
		}
	}

	startX := -minX
	startY := -minY

	for i := 0; i < size; i++ {
		for j := 0; j < size; j++ {
			vis[i][j] = 1
		}
	}

	currX, currY := startX, startY
	for i := 0; i < lenS; i++ {
		switch s[i] {
		case 'L':
			currY--
		case 'R':
			currY++
		case 'U':
			currX--
		case 'D':
			currX++
		}
		if currX >= 0 && currX < size && currY >= 0 && currY < size {
			vis[currX][currY] = 0
		}
	}

	ans := bfs(startX, startY, currX, currY)

	if ans == lenS {
		fmt.Println("OK")
	} else {
		fmt.Println("BUG")
	}
}

