package main

import (
	"container/heap"
	"fmt"
)

const N = 110

var vis [N][N]int
var f = [4][2]int{{0, 1}, {1, 0}, {0, -1}, {-1, 0}}

type Node struct {
	x, y, step int
	index      int
}

type PriorityQueue []*Node

func (pq PriorityQueue) Len() int            { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool  { return pq[i].step < pq[j].step }
func (pq PriorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i]; pq[i].index = i; pq[j].index = j }
func (pq *PriorityQueue) Push(x interface{}) { n := len(*pq); item := x.(*Node); item.index = n; *pq = append(*pq, item) }
func (pq *PriorityQueue) Pop() interface{}   { old := *pq; n := len(old); item := old[n-1]; old[n-1] = nil; item.index = -1; *pq = old[0 : n-1]; return item }

func bfs(l, u, xi, yi int) int {
	pq := make(PriorityQueue, 0)
	heap.Init(&pq)
	start := &Node{x: l, y: u, step: 0}
	heap.Push(&pq, start)
	vis[l][u] = 1

	for pq.Len() > 0 {
		e := heap.Pop(&pq).(*Node)
		if e.x == xi && e.y == yi {
			return e.step
		}
		for i := 0; i < 4; i++ {
			t := &Node{x: e.x + f[i][0], y: e.y + f[i][1], step: e.step + 1}
			if t.x < 0 || t.y < 0 || t.x >= N || t.y >= N {
				continue
			}
			if vis[t.x][t.y] == 1 {
				continue
			}
			vis[t.x][t.y] = 1
			heap.Push(&pq, t)
		}
	}
	return -1
}

func main() {
	var s string
	fmt.Scanln(&s)
	lenS := len(s)
	x, y := 0, 0
	xx, yy := 0, 0

	for i := 0; i < lenS; i++ {
		switch s[i] {
		case 'L':
			y--
		case 'R':
			y++
		case 'U':
			x--
		case 'D':
			x++
		}
		if x < xx {
			xx = x
		}
		if y < yy {
			yy = y
		}
	}
	xx = -xx
	yy = -yy

	for i := 0; i < N; i++ {
		for j := 0; j < N; j++ {
			vis[i][j] = 1
		}
	}

	x, y = xx, yy
	for i := 0; i < lenS; i++ {
